-- 5. Extension des types d'approbations dans approbations_operations pour gouvernance
-- Recréation propre de la table approbations_operations pour autoriser REFERENCE_CADRE_REGLEMENTAIRE et AUTORISATION_OUVERTURE
CREATE TABLE approbations_operations_nouvelle (
    id TEXT PRIMARY KEY,
    operation_id TEXT NOT NULL REFERENCES operations_centrales_distribution(id) ON DELETE CASCADE,
    type_approbation TEXT NOT NULL CHECK (type_approbation IN ('COMITE_PILOTAGE', 'APPROBATION_COMITE_PILOTAGE', 'VALIDATION_MINISTERIELLE', 'AUTORISATION_OUVERTURE', 'AUTORISATION_SPECIALISEE', 'REFERENCE_CADRE_REGLEMENTAIRE')),
    instance_decisionnaire TEXT NOT NULL,
    reference_acte TEXT NOT NULL,
    date_decision TEXT NOT NULL,
    signataire_nom TEXT NOT NULL,
    signataire_qualite TEXT NOT NULL,
    decision TEXT NOT NULL CHECK (decision IN ('APPROUVE', 'REJETE', 'AJOURNE', 'APPROUVE_AVEC_RESERVES')),
    reserves_ou_conditions TEXT,
    piece_jointe_id TEXT REFERENCES pieces_jointes(id),
    enregistre_par TEXT NOT NULL REFERENCES utilisateurs(id),
    enregistre_le TEXT NOT NULL DEFAULT (datetime('now'))
);
INSERT INTO approbations_operations_nouvelle SELECT * FROM approbations_operations;
DROP TABLE approbations_operations;
ALTER TABLE approbations_operations_nouvelle RENAME TO approbations_operations;
CREATE INDEX IF NOT EXISTS idx_approbations_op ON approbations_operations(operation_id);
CREATE INDEX IF NOT EXISTS idx_approbations_op_type ON approbations_operations(type_approbation);
CREATE INDEX IF NOT EXISTS idx_approbations_op_decision ON approbations_operations(decision);

PRAGMA foreign_keys = ON;